translation.example:
import numpy as np
from BB import spg
def fn(x):
    return np.sum((np.asarray(x, dtype=float) - np.array([1.0, 2.0, 3.0])) ** 2)
def gr(x):
    return 2 * (np.asarray(x, dtype=float) - np.array([1.0, 2.0, 3.0]))
def one():
    res = spg([0.0, 0.0, 0.0], fn, gr, control={"checkGrad": False, "trace": False}, quiet=True)
    return np.concatenate([res["par"], [res["value"], res["gradient"], res["fn.reduction"], res["iter"], res["feval"], res["convergence"]]])
print(one())
